package com.amplayer.portable;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.provider.MediaStore;import org.json.*;import java.io.*;import java.nio.*;import java.util.ArrayList;
public class LocalPlaybackInstrumentation extends Instrumentation {
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();Uri uri=null,copied=null;try{
  for(String charset:new String[]{"UTF-8","Big5","GB18030","Shift_JIS","EUC-KR"}){String expected=charset.equals("Shift_JIS")?"日本の音楽":charset.equals("EUC-KR")?"한국 음악":"中文音樂";if(!AudioTags.decode(expected.getBytes(charset),0,charset,"zh-TW").equals(expected))throw new Exception("Encoding failed: "+charset);}
  result.putString("encoding","PASS: UTF-8, Big5, GB18030, Shift-JIS, EUC-KR");
  JSONObject settings=Store.load(getTargetContext());settings.put("volume",0).put("autoUpdate",false);Store.save(getTargetContext(),settings.toString());Activity activity=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();Thread.sleep(3000);
  ContentValues values=new ContentValues();values.put(MediaStore.Audio.Media.DISPLAY_NAME,"AMPlayer-instrumentation-"+System.currentTimeMillis()+".wav");values.put(MediaStore.Audio.Media.MIME_TYPE,"audio/wav");values.put(MediaStore.Audio.Media.RELATIVE_PATH,"Music/AMPlayerTest");uri=getTargetContext().getContentResolver().insert(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new Exception("Test media creation failed");
  int bytes=16000*40;ByteBuffer wave=ByteBuffer.allocate(44+bytes).order(ByteOrder.LITTLE_ENDIAN);wave.put("RIFF".getBytes()).putInt(36+bytes).put("WAVEfmt ".getBytes()).putInt(16).putShort((short)1).putShort((short)1).putInt(8000).putInt(16000).putShort((short)2).putShort((short)16).put("data".getBytes()).putInt(bytes);try(OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){out.write(wave.array());}
  JSONObject item=new JSONObject().put("name","Local content URI test").put("type","local").put("path",uri.toString());runOnMainSync(()->getTargetContext().startForegroundService(new Intent(getTargetContext(),PlaybackService.class).setAction("item").putExtra("item",item.toString())));
  JSONObject status=new JSONObject();for(int i=0;i<60;i++){Thread.sleep(500);status=new JSONObject(PlaybackService.status());if(status.optBoolean("playing")&&status.optLong("position")>300)break;}if(!status.optBoolean("playing"))throw new Exception(status.toString());result.putString("localPlayback",status.toString());
  runOnMainSync(()->activity.moveTaskToBack(true));Thread.sleep(400);IncomingMusic.accept(getTargetContext(),new Intent(Intent.ACTION_SEND).setType("audio/wav").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));JSONObject received=new JSONObject();for(int i=0;i<40;i++){Thread.sleep(150);JSONObject next=IncomingMusic.drain(getTargetContext());if(next.optJSONArray("items")!=null&&next.getJSONArray("items").length()>0){received=next;break;}}if(received.optJSONArray("items")==null)throw new Exception("Shared import missing");JSONObject shared=received.getJSONArray("items").getJSONObject(0);if(!shared.optBoolean("owned")||!shared.getString("path").contains(".shared/"))throw new Exception("Shared file not in app Music");copied=Uri.parse(shared.getString("path"));
  ArrayList<Uri> duplicates=new ArrayList<>();duplicates.add(uri);duplicates.add(uri);IncomingMusic.accept(getTargetContext(),new Intent(Intent.ACTION_SEND_MULTIPLE).setType("audio/wav").putParcelableArrayListExtra(Intent.EXTRA_STREAM,duplicates).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));Thread.sleep(900);JSONObject again=IncomingMusic.drain(getTargetContext());if(again.optJSONArray("items")==null||!again.getJSONArray("items").getJSONObject(0).getString("path").equals(copied.toString()))throw new Exception("Shared duplicate not reused");result.putString("sharing","PASS: SEND / SEND_MULTIPLE imported into app Music with stable content hash");
  JSONObject sharedItem=shared;runOnMainSync(()->getTargetContext().startForegroundService(new Intent(getTargetContext(),PlaybackService.class).setAction("item").putExtra("item",sharedItem.toString())));for(int wait=0;wait<40;wait++){Thread.sleep(500);JSONObject check=new JSONObject(PlaybackService.status());if(check.optBoolean("playing")&&check.optJSONObject("item")!=null&&check.getJSONObject("item").optString("path").equals(sharedItem.optString("path")))break;}if(!new JSONObject(PlaybackService.status()).optBoolean("playing"))throw new Exception("App Music file playback failed");
result.putString("result","PASS: local content URI played with no storage or microphone permission");finish(Activity.RESULT_OK,result);
 }catch(Exception e){result.putString("failure",e.toString());finish(Activity.RESULT_CANCELED,result);}finally{getTargetContext().stopService(new Intent(getTargetContext(),PlaybackService.class));if(uri!=null)getTargetContext().getContentResolver().delete(uri,null,null);if(copied!=null){File f=new File(new File(getTargetContext().getFilesDir(),"Music"),copied.getLastPathSegment());f.delete();new File(f.getPath()+".json").delete();}}}
}
